import { AuthenticationError } from "@formbricks/types/errors";
import { AccountSecurity } from "@/app/(app)/workspaces/[workspaceId]/settings/account/profile/components/AccountSecurity";
import { DeleteAccount } from "@/app/(app)/workspaces/[workspaceId]/settings/account/profile/components/DeleteAccount";
import { EditProfileDetailsForm } from "@/app/(app)/workspaces/[workspaceId]/settings/account/profile/components/EditProfileDetailsForm";
import { SettingsCard } from "@/app/(app)/workspaces/[workspaceId]/settings/components/SettingsCard";
import {
  EMAIL_VERIFICATION_DISABLED,
  ENTERPRISE_LICENSE_REQUEST_FORM_URL,
  IS_FORMBRICKS_CLOUD,
  PASSWORD_RESET_DISABLED,
} from "@/lib/constants";
import { getOrganizationsWhereUserIsSingleOwner } from "@/lib/organization/service";
import { getUser } from "@/lib/user/service";
import { getTranslate } from "@/lingodotdev/server";
import { requiresPasswordConfirmationForAccountDeletion } from "@/modules/account/lib/account-deletion-auth";
import { getSession } from "@/modules/auth/lib/session";
import { LiteLicenseTip } from "@/modules/ee/license-check/components/lite-license-tip";
import { getEnterpriseLicense } from "@/modules/ee/license-check/lib/license";
import { getIsMultiOrgEnabled, getIsTwoFactorAuthEnabled } from "@/modules/ee/license-check/lib/utils";
import { getSettingsLayoutData } from "@/modules/settings/lib/navigation-data";
import { getOrganizationBillingPath } from "@/modules/settings/lib/routes";
import { IdBadge } from "@/modules/ui/components/id-badge";
import { PageContentWrapper } from "@/modules/ui/components/page-content-wrapper";
import { PageHeader } from "@/modules/ui/components/page-header";
import { UpgradePrompt } from "@/modules/ui/components/upgrade-prompt";

const Page = async () => {
  const isTwoFactorAuthEnabled = await getIsTwoFactorAuthEnabled();
  const isMultiOrgEnabled = await getIsMultiOrgEnabled();
  const t = await getTranslate();
  const session = await getSession();
  if (!session?.user) {
    throw new AuthenticationError(t("common.not_authenticated"));
  }

  const organizationsWithSingleOwner = await getOrganizationsWhereUserIsSingleOwner(session.user.id);
  const user = await getUser(session.user.id);
  if (!user) {
    throw new AuthenticationError(t("common.not_authenticated"));
  }

  // Two-factor upgrade points at the user's organization billing page (org-scoped after the refactor).
  const layoutData = await getSettingsLayoutData(session.user.id);
  const billingUpgradeHref = layoutData
    ? getOrganizationBillingPath(layoutData.organization.id, IS_FORMBRICKS_CLOUD)
    : "/";

  const canUseTwoFactorAuth = isTwoFactorAuthEnabled || user.twoFactorEnabled;
  // Self-hosted without any license key: 2FA is part of the free Lite license, so offer that instead
  // of the paid upgrade.
  const showTwoFactorLiteLicenseTip =
    !canUseTwoFactorAuth && !IS_FORMBRICKS_CLOUD && (await getEnterpriseLicense()).status === "no-license";

  let securityContent: React.ReactNode;
  if (canUseTwoFactorAuth) {
    securityContent = <AccountSecurity user={user} />;
  } else if (showTwoFactorLiteLicenseTip) {
    securityContent = (
      <LiteLicenseTip
        feature="two_factor_auth"
        title={t("workspace.settings.profile.two_factor_authentication_lite_license_title")}
        description={t("common.lite_license_tip_description")}
      />
    );
  } else {
    securityContent = (
      <UpgradePrompt
        title={t("workspace.settings.profile.unlock_two_factor_authentication")}
        description={t("workspace.settings.profile.two_factor_authentication_description")}
        buttons={[
          {
            text: IS_FORMBRICKS_CLOUD ? t("common.upgrade_plan") : t("common.request_trial_license"),
            href: IS_FORMBRICKS_CLOUD ? billingUpgradeHref : ENTERPRISE_LICENSE_REQUEST_FORM_URL,
          },
          {
            text: t("common.learn_more"),
            href: IS_FORMBRICKS_CLOUD
              ? billingUpgradeHref
              : "https://formbricks.com/learn-more-self-hosting-license?utm_source=formbricks-app&utm_medium=webapp&utm_campaign=ee_lock_two_factor",
          },
        ]}
      />
    );
  }

  const isPasswordResetEnabled = !PASSWORD_RESET_DISABLED && user.identityProvider === "email";
  const requiresPasswordConfirmation = requiresPasswordConfirmationForAccountDeletion(user);

  return (
    <PageContentWrapper>
      <PageHeader pageTitle={t("common.profile")} />
      <div>
        <SettingsCard
          title={t("workspace.settings.profile.personal_information")}
          description={t("workspace.settings.profile.update_personal_info")}>
          <EditProfileDetailsForm
            user={user}
            emailVerificationDisabled={EMAIL_VERIFICATION_DISABLED}
            isPasswordResetEnabled={isPasswordResetEnabled}
          />
        </SettingsCard>
        {user.identityProvider === "email" && (
          <SettingsCard
            title={t("common.security")}
            description={t("workspace.settings.profile.security_description")}
            bodyVariant={showTwoFactorLiteLicenseTip ? "bleed" : "padded"}>
            {securityContent}
          </SettingsCard>
        )}

        <SettingsCard
          title={t("workspace.settings.profile.delete_account")}
          description={t("workspace.settings.profile.confirm_delete_account")}>
          <DeleteAccount
            session={session}
            IS_FORMBRICKS_CLOUD={IS_FORMBRICKS_CLOUD}
            user={user}
            organizationsWithSingleOwner={organizationsWithSingleOwner}
            isMultiOrgEnabled={isMultiOrgEnabled}
            requiresPasswordConfirmation={requiresPasswordConfirmation}
          />
        </SettingsCard>
        <IdBadge id={user.id} label={t("common.profile_id")} variant="column" />
      </div>
    </PageContentWrapper>
  );
};

export default Page;

import { redirect } from "next/navigation";
import { getSession } from "@/modules/auth/lib/session";
import { SettingsShell } from "@/modules/settings/components/settings-shell";
import { getSettingsLayoutData } from "@/modules/settings/lib/navigation-data";

const AccountSettingsLayout = async ({ children }: Readonly<{ children: React.ReactNode }>) => {
  const session = await getSession();
  if (!session?.user) {
    return redirect("/auth/login");
  }

  const data = await getSettingsLayoutData(session.user.id);
  if (!data) {
    return redirect("/");
  }

  return <SettingsShell data={data}>{children}</SettingsShell>;
};

export default AccountSettingsLayout;

"use client";

import { useTranslation } from "react-i18next";
import { cn } from "@/lib/cn";
import { Badge } from "@/modules/ui/components/badge";
import { Button } from "@/modules/ui/components/button";
import { H4, Small } from "@/modules/ui/components/typography";

interface ButtonInfo {
  text: string;
  onClick: () => void;
  variant: "secondary" | "default" | "outline" | "ghost" | "link";
}

/**
 * How the card treats its body:
 * - `padded` — the default `px-4 pt-4` gutter, for ordinary form content.
 * - `bleed` — no gutter; the child supplies its own padding.
 * - `flush` — no gutter *and* no bottom padding, so edge-to-edge content (a table) meets the card's
 *   bottom border. Pairs with `overflow-hidden` on the card, which clips the content with the card's
 *   own inner radius — a `rounded-b-*` on the child would be off by the border width.
 */
export type TSettingsCardBodyVariant = "padded" | "bleed" | "flush";

const BODY_VARIANT_CLASSES: Record<TSettingsCardBodyVariant, string> = {
  padded: "px-4 pt-4",
  bleed: "",
  flush: "-mb-4",
};

export const SettingsCard = ({
  title,
  description,
  children,
  soon = false,
  bodyVariant = "padded",
  beta,
  className,
  buttonInfo,
  cta,
}: {
  title: string;
  description: string;
  children: any;
  soon?: boolean;
  bodyVariant?: TSettingsCardBodyVariant;
  beta?: boolean;
  className?: string;
  buttonInfo?: ButtonInfo;
  cta?: React.ReactNode;
}) => {
  const { t } = useTranslation();
  return (
    <div
      className={cn(
        "relative my-4 w-full max-w-4xl rounded-xl border border-slate-200 bg-white py-4 text-left shadow-xs",
        bodyVariant === "flush" && "overflow-hidden",
        className
      )}
      id={title}>
      <div className="flex justify-between border-b border-slate-200 px-4 pb-4">
        <div>
          <H4 className="font-medium tracking-normal">{title}</H4>
          <div className="ml-2">
            {beta && <Badge size="normal" type="warning" text="Beta" />}
            {soon && (
              <Badge size="normal" type="success" text={t("workspace.settings.enterprise.coming_soon")} />
            )}
          </div>
          <Small color="muted" margin="headerDescription">
            {description}
          </Small>
        </div>
        {cta ??
          (buttonInfo && (
            <Button type="button" onClick={buttonInfo?.onClick} variant={buttonInfo?.variant ?? "default"}>
              {buttonInfo?.text}
            </Button>
          ))}
      </div>
      <div className={BODY_VARIANT_CLASSES[bodyVariant]}>{children}</div>
    </div>
  );
};

import "server-only";
import { cache as reactCache } from "react";
import { z } from "zod";
import { prisma } from "@formbricks/database";
import { Prisma } from "@formbricks/database/prisma";
import { PrismaErrorType } from "@formbricks/database/types/error";
import { ZId } from "@formbricks/types/common";
import { DatabaseError, ResourceNotFoundError } from "@formbricks/types/errors";
import { TUser, TUserLocale, TUserUpdateInput, ZUserUpdateInput } from "@formbricks/types/user";
import { deleteUserOrganizationRelationships } from "@/lib/authzed/organization-membership";
import { runPostCommitProjection } from "@/lib/authzed/projection-boundary";
import { deleteUserTeamRelationships } from "@/lib/authzed/team-workspace";
import { deleteOrganization, getOrganizationsWhereUserIsSingleOwner } from "@/lib/organization/service";
import { deleteBrevoCustomerByEmail } from "@/modules/auth/lib/brevo";
import { normalizeEmailForComparison } from "../utils/email";
import { validateInputs } from "../utils/validate";
import { publicUserSelect } from "./public-user";

// function to retrive basic information about a user's user
export const getUser = reactCache(async (id: string): Promise<TUser | null> => {
  validateInputs([id, ZId]);

  try {
    const user = await prisma.user.findUnique({
      where: {
        id,
      },
      select: publicUserSelect,
    });

    if (!user) {
      return null;
    }
    return user;
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new DatabaseError(error.message);
    }

    throw error;
  }
});

/**
 * Look a user up by email address.
 *
 * Canonicalized before the query, for the reason spelled out on `normalizeEmailForComparison` and on
 * the sibling lookup in `modules/auth/lib/user.ts`: Postgres compares `text` case-sensitively while
 * Better Auth stores and looks up `email.toLowerCase()`, and a lookup that can disagree with Better
 * Auth is the ENG-3257 defect. Today's callers here already lowercase before calling; normalizing in
 * the query is what stops the next one from having to know that.
 */
export const getUserByEmail = reactCache(async (email: string): Promise<TUser | null> => {
  validateInputs([email, z.email()]);

  try {
    const user = await prisma.user.findFirst({
      where: {
        email: normalizeEmailForComparison(email),
      },
      select: publicUserSelect,
    });

    return user;
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new DatabaseError(error.message);
    }

    throw error;
  }
});

// function to update a user's user
export const updateUser = async (personId: string, data: TUserUpdateInput): Promise<TUser> => {
  validateInputs([personId, ZId], [data, ZUserUpdateInput.partial()]);

  try {
    const updatedUser = await prisma.user.update({
      where: {
        id: personId,
      },
      data: data,
      select: publicUserSelect,
    });

    return updatedUser;
  } catch (error) {
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === PrismaErrorType.RecordNotFound
    ) {
      throw new ResourceNotFoundError("User", personId);
    }
    throw error; // Re-throw any other errors
  }
};

const deleteUserById = async (id: string): Promise<TUser> => {
  validateInputs([id, ZId]);

  try {
    const user = await prisma.user.delete({
      where: {
        id,
      },
      select: publicUserSelect,
    });
    return user;
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new DatabaseError(error.message);
    }

    throw error;
  }
};

// function to delete a user's user including organizations
export const deleteUser = async (id: string): Promise<TUser> => {
  validateInputs([id, ZId]);

  try {
    const organizationsWithSingleOwner = await getOrganizationsWhereUserIsSingleOwner(id);

    for (const organization of organizationsWithSingleOwner) {
      await deleteOrganization(organization.id);
    }

    await prisma.invite.deleteMany({ where: { creatorId: id } });

    const deletedUser = await deleteUserById(id);
    await runPostCommitProjection("user_delete_organization_cleanup", () =>
      deleteUserOrganizationRelationships(id)
    );
    await runPostCommitProjection("user_delete_team_cleanup", () => deleteUserTeamRelationships(id));
    await deleteBrevoCustomerByEmail({ email: deletedUser.email });

    return deletedUser;
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new DatabaseError(error.message);
    }

    throw error;
  }
};

export const getUsersWithOrganization = async (organizationId: string): Promise<TUser[]> => {
  validateInputs([organizationId, ZId]);

  try {
    const users = await prisma.user.findMany({
      where: {
        memberships: {
          some: {
            organizationId,
          },
        },
      },
      select: publicUserSelect,
    });

    return users;
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new DatabaseError(error.message);
    }

    throw error;
  }
};

export const getUserLocale = reactCache(async (id: string): Promise<TUserLocale | undefined> => {
  validateInputs([id, ZId]);

  try {
    const user = await prisma.user.findUnique({
      where: {
        id,
      },
      select: publicUserSelect,
    });

    if (!user) {
      return undefined;
    }
    return user.locale;
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new DatabaseError(error.message);
    }

    throw error;
  }
});

import "server-only";
import { isAPIError } from "better-auth/api";
import { headers } from "next/headers";
import { cache } from "react";
import { prisma } from "@formbricks/database";
import { logger } from "@formbricks/logger";
import type { Session } from "@formbricks/types/auth";
import { auth } from "@/modules/auth/lib/auth";

/**
 * Request-scoped session read — the single identity choke point for the app (ENG-1054 DAL).
 *
 * Cutover: reads the Better Auth session ONLY (`auth.api.getSession`), wrapped in React `cache()`
 * for per-request dedupe and marked `server-only`. NextAuth cookies are intentionally NOT honored —
 * the cutover is a one-time forced re-login (sessions aren't portable across Better Auth's cookie
 * signing + the schema change; see eng-1054-cutover-runbook.md §0/D3), so there is deliberately no
 * dual-read. Centralizing every read here keeps the flip a single-file change rather than a sweep of
 * the ~33 former `getServerSession` call sites.
 *
 * Returns the same `Session` shape those call sites already consume (`session.user.id` +
 * `session.user.email`; see packages/types/auth.ts) so it stays a drop-in. A 2FA-pending login
 * resolves to `null`: Better Auth deletes the credential session and issues a short-lived
 * two-factor cookie until the code is verified, so no authenticated session exists yet.
 */
/**
 * The Postgres `Session` row is the authority on whether a session exists; Redis and the cookie cache
 * are only copies of it.
 *
 * Better Auth serves this session from Redis secondary storage and a 5-minute signed cookie cache, so
 * neither the session record nor `result.user` reflects a session whose row was deleted, or a user who
 * was deactivated, after signing in. `rejectInactiveUserOnSessionCreate` only gates session *creation*.
 * Without this read a deactivated user keeps full access — server actions, v3 session routes, storage —
 * for the life of a rolling 1-day session, and a session whose row is gone (a user-delete cascade, a bare
 * `prisma.session.deleteMany()`, a restore) stays valid until its Redis TTL (ENG-3418). It is the same
 * lookup `getProxySession` makes for the middleware, so the two cannot disagree on who is signed in.
 */
const isSessionLive = async (sessionToken: string, userId: string): Promise<boolean> => {
  const session = await prisma.session.findUnique({
    where: { sessionToken },
    select: { userId: true, user: { select: { isActive: true } } },
  });

  // A session whose user row is gone has no row either: the delete cascades.
  return session?.userId === userId && session.user.isActive === true;
};

/**
 * Better Auth's answer when a session it just served from Redis cannot be refreshed in Postgres: it
 * deletes the session cookie and throws `UNAUTHORIZED` / `FAILED_TO_GET_SESSION`
 * (`better-auth/dist/api/routes/session.mjs`, "concurrent deletion"). That is a signed-out user, not a
 * fault — left uncaught it crashes the page instead of redirecting to login (ENG-3418). Any other error,
 * such as `INTERNAL_SERVER_ERROR` when both stores fail, is a real outage and still throws.
 * `better-auth-session-fallback.test.ts` fails if a version bump changes this error's shape.
 */
const isVanishedSessionError = (error: unknown): boolean =>
  isAPIError(error) &&
  error.status === "UNAUTHORIZED" &&
  (error.body as { code?: string } | undefined)?.code === "FAILED_TO_GET_SESSION";

const getBetterAuthSession = async () => {
  try {
    return await auth.api.getSession({ headers: await headers() });
  } catch (error) {
    if (!isVanishedSessionError(error)) throw error;
    logger.warn("Better Auth could not refresh a session missing from the database; treating as signed out");
    return null;
  }
};

export const getSession = cache(async (): Promise<Session | null> => {
  const result = await getBetterAuthSession();
  if (!result?.user) {
    return null;
  }

  if (!(await isSessionLive(result.session.token, result.user.id))) {
    return null;
  }

  return {
    user: {
      id: result.user.id,
      email: result.user.email,
      name: result.user.name,
    },
    // BA exposes `expiresAt` as a Date, but secondary-storage round-trips can hand back a string;
    // normalize both to the ISO string NextAuth's `Session.expires` contract guarantees.
    expires: new Date(result.session.expiresAt).toISOString(),
  };
});

import { z } from "zod";

export const ZUserLocale = z.enum([
  "de-DE",
  "en-US",
  "es-ES",
  "fr-FR",
  "hu-HU",
  "ja-JP",
  "nl-NL",
  "pt-BR",
  "pt-PT",
  "ro-RO",
  "ru-RU",
  "sv-SE",
  "tr-TR",
  "zh-Hans-CN",
  "zh-Hant-TW",
]);

export type TUserLocale = z.infer<typeof ZUserLocale>;

export const ZUserNotificationSettings = z.object({
  alert: z.record(z.string(), z.boolean()),
  unsubscribedOrganizationIds: z.array(z.string()).optional(),
});

// Characters allowed in a user's display name: letters, combining marks, space, and common name
// punctuation — apostrophe, comma, period, ampersand, parentheses, digits, hyphen. `.` and `&` were
// added for ENG-1743 so ordinary names ("J. Smith", "Smith & Co") validate instead of being rejected.
// Declared once so the validator (ZUserName) and the normalizer (normalizeUserName) can never diverge:
// every string normalizeUserName produces is guaranteed to satisfy ZUserName. `-` stays last so it is
// a literal, not a range.
const USER_NAME_ALLOWED_CHARS = "\\p{L}\\p{M} ',.&()\\d-";

export const ZUserName = z
  .string()
  .trim()
  .min(1, {
    error: "Name should be at least 1 character long",
  })
  .regex(new RegExp(`^[${USER_NAME_ALLOWED_CHARS}]+$`, "u"), "Invalid name format");

/**
 * Normalize an untrusted display name (e.g. an SSO identity-provider name) into a value that always
 * satisfies {@link ZUserName}: characters outside the allowlist collapse to a single space, internal
 * whitespace is collapsed, and the result is trimmed. External IdP names are untrusted input, so we
 * sanitize them to fit the model rather than rejecting the sign-in (ENG-1743). Returns "" when nothing
 * survives (e.g. a name of only emoji); callers should fall back to another source such as the email
 * local-part.
 */
export const normalizeUserName = (name: string): string =>
  name
    .replace(new RegExp(`[^${USER_NAME_ALLOWED_CHARS}]+`, "gu"), " ")
    .replace(/\s+/gu, " ")
    .trim();

export const ZUserEmail = z
  .email({
    error: "Invalid email",
  })
  .max(255);

export type TUserEmail = z.infer<typeof ZUserEmail>;

export const ZUserPassword = z
  .string()
  .min(8, {
    error: "Password must be at least 8 characters long",
  })
  .max(128, {
    error: "Password must be 128 characters or less",
  })
  .regex(/^(?=.*[A-Z])(?=.*\d).*$/);

export type TUserPassword = z.infer<typeof ZUserPassword>;

export type TUserNotificationSettings = z.infer<typeof ZUserNotificationSettings>;

const ZUserIdentityProvider = z.enum(["email", "google", "github", "azuread", "openid", "saml"]);

export const ZUser = z.object({
  id: z.string(),
  name: ZUserName,
  email: ZUserEmail,
  emailVerified: z.boolean(),
  twoFactorEnabled: z.boolean(),
  identityProvider: ZUserIdentityProvider,
  createdAt: z.date(),
  updatedAt: z.date(),
  notificationSettings: ZUserNotificationSettings,
  locale: ZUserLocale,
  lastLoginAt: z.date().nullable(),
  isActive: z.boolean().prefault(true),
});

export type TUser = z.infer<typeof ZUser>;

export const ZUserUpdateInput = z.object({
  name: ZUserName.optional(),
  email: ZUserEmail.optional(),
  emailVerified: z.boolean().optional(),
  password: ZUserPassword.optional(),
  notificationSettings: ZUserNotificationSettings.optional(),
  locale: ZUserLocale.optional(),
  lastLoginAt: z.date().nullish(),
  isActive: z.boolean().optional(),
});

export type TUserUpdateInput = z.infer<typeof ZUserUpdateInput>;

export const ZUserCreateInput = z.object({
  name: ZUserName,
  email: ZUserEmail,
  password: ZUserPassword.optional(),
  emailVerified: z.boolean().optional(),
  identityProvider: ZUserIdentityProvider.optional(),
  identityProviderAccountId: z.string().optional(),
  locale: ZUserLocale.optional(),
});

export type TUserCreateInput = z.infer<typeof ZUserCreateInput>;

export const ZUserPersonalInfoUpdateInput = ZUserUpdateInput.pick({
  name: true,
  email: true,
  locale: true,
}).extend({
  password: ZUserPassword.optional(),
});

export type TUserPersonalInfoUpdateInput = z.infer<typeof ZUserPersonalInfoUpdateInput>;

import "server-only";
import { prisma } from "@formbricks/database";
import type { OrganizationRole } from "@formbricks/database/prisma";
import { type TAuthzedClient, type TAuthzedRelationshipUpdate, getAuthzedClient } from "./client";
import {
  AUTHZED_MAX_RECONCILIATION_PASSES,
  AuthzedProjectionUnstableError,
  type TAuthzedProjectionResult,
  runBestEffortProjection,
} from "./projection";
import { packRelationshipUpdateGroups } from "./relationship-batches";
import { ORGANIZATION_RELATIONS } from "./relationship-map";

export type { TAuthzedProjectionResult } from "./projection";

const ORGANIZATION_RELATION_NAMES = Object.values(ORGANIZATION_RELATIONS);

export type TOrganizationMembershipProjectionTarget = Readonly<{
  organizationId: string;
  userId: string;
}>;

export type TOrganizationMembershipProjectionTargets = Readonly<{
  memberships?: ReadonlyArray<TOrganizationMembershipProjectionTarget>;
}>;

type TOrganizationMembershipSnapshot = ReadonlyArray<
  Readonly<{ organizationId: string; role: OrganizationRole; userId: string }>
>;

/** Length-prefixed so `("ab", "c")` and `("a", "bc")` cannot collide. */
const pairKey = (first: string, second: string): string => `${first.length}:${first}${second}`;

const normalizeTargets = (
  targets: TOrganizationMembershipProjectionTargets
): ReadonlyArray<TOrganizationMembershipProjectionTarget> => {
  const uniqueTargets = new Map<string, TOrganizationMembershipProjectionTarget>();

  for (const target of targets.memberships ?? []) {
    uniqueTargets.set(pairKey(target.organizationId, target.userId), target);
  }

  // Deterministic ordering is what makes the snapshot comparison below a plain string equality.
  return [...uniqueTargets.values()].sort((left, right) =>
    pairKey(left.organizationId, left.userId).localeCompare(pairKey(right.organizationId, right.userId))
  );
};

const readSnapshot = async (
  targets: ReadonlyArray<TOrganizationMembershipProjectionTarget>
): Promise<TOrganizationMembershipSnapshot> =>
  prisma.membership.findMany({
    where: {
      OR: targets.map(({ organizationId, userId }) => ({ organizationId, userId })),
    },
    // The current contract does not gate organization membership on `accepted`. Project every row so
    // the SpiceDB graph preserves that behavior exactly.
    select: { organizationId: true, role: true, userId: true },
    orderBy: [{ organizationId: "asc" }, { userId: "asc" }],
  });

const snapshotsMatch = (
  left: TOrganizationMembershipSnapshot,
  right: TOrganizationMembershipSnapshot
): boolean => JSON.stringify(left) === JSON.stringify(right);

const createMembershipUpdates = (
  target: TOrganizationMembershipProjectionTarget,
  role: OrganizationRole | null
): ReadonlyArray<TAuthzedRelationshipUpdate> =>
  ORGANIZATION_RELATION_NAMES.map((relation) => ({
    operation: role !== null && relation === ORGANIZATION_RELATIONS[role] ? "touch" : "delete",
    relationship: {
      relation,
      resource: { objectId: target.organizationId, objectType: "organization" },
      subject: { objectId: target.userId, objectType: "user" },
    },
  }));

const writeSnapshot = async (
  client: TAuthzedClient,
  targets: ReadonlyArray<TOrganizationMembershipProjectionTarget>,
  snapshot: TOrganizationMembershipSnapshot
): Promise<void> => {
  const rolesByPair = new Map(
    snapshot.map((membership) => [pairKey(membership.organizationId, membership.userId), membership.role])
  );

  // A target with no row yields four deletes, so a membership removed outside a mutation hook — or
  // one that only ever existed in SpiceDB — is healed by being named here.
  const updateGroups = targets.map((target) => [
    ...createMembershipUpdates(
      target,
      rolesByPair.get(pairKey(target.organizationId, target.userId)) ?? null
    ),
  ]);

  for (const batch of packRelationshipUpdateGroups(updateGroups)) {
    await client.writeRelationships(batch);
  }
};

/**
